/**
 * The small libraries a check imports to reach the app from outside: the
 * HTTP API through `THISISFINE_BASE_URL`, the cli through `THISISFINE_CLI`,
 * and files through a scratch directory. One per runner, same three verbs,
 * so a promise reads the same whatever language checks it. Generated into
 * `.thisisfine/` (and regenerated by every `init`), never into the app.
 */

export const PYTEST_VERSION = "8.3.3";
export const REQUESTS_VERSION = "2.32.3";

/** Playwright fixtures. A check does `import { test, expect } from "../tif";`. */
export const TIF_TS = String.raw`// Generated by thisisfine; "thisisfine init" rewrites it.
// Checks import from here to reach the app from outside:
//   test("...", async ({ page, request, run, write, read }) => { ... })
import { test as base, expect } from "@playwright/test";
import { spawn } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";

export interface Result { code: number; out: string; err: string }

interface Fixtures {
  /** The cli's working directory for this test (fresh each time). */
  work: string;
  /** Runs the configured cli with these args; never throws on a non-zero exit. */
  run: (args: string[], opts?: { input?: string }) => Promise<Result>;
  /** Writes a file inside the scratch directory, for the cli to read. */
  write: (path: string, text: string) => string;
  /** Reads a file the cli wrote in the scratch directory (null when it isn't there). */
  read: (path: string) => string | null;
}

function inside(work: string, path: string): string {
  const full = resolve(work, path);
  if (relative(work, full).startsWith("..")) throw new Error("thisisfine: " + path + " is outside the scratch directory");
  return full;
}

export const test = base.extend<Fixtures>({
  work: async ({}, use, info) => {
    const dir = join(info.outputDir, "work");
    mkdirSync(dir, { recursive: true });
    await use(dir);
  },
  run: async ({ work }, use) => {
    await use((args, opts = {}) => new Promise<Result>((done, fail) => {
      const cli = JSON.parse(process.env.THISISFINE_CLI || "null") as string[] | null;
      if (!cli) return fail(new Error('thisisfine: no cli to run. Set "cli" in .thisisfine/config.json.'));
      const child = spawn(cli[0]!, [...cli.slice(1), ...args], { env: { ...process.env, THISISFINE_WORK: work }, windowsHide: true });
      let out = "";
      let err = "";
      child.stdout.on("data", (c) => (out += c));
      child.stderr.on("data", (c) => (err += c));
      child.on("error", fail);
      child.on("close", (code) => done({ code: code ?? 1, out, err }));
      child.stdin.end(opts.input ?? "");
    }));
  },
  write: async ({ work }, use) => {
    await use((path, text) => {
      const full = inside(work, path);
      mkdirSync(dirname(full), { recursive: true });
      writeFileSync(full, text);
      return full;
    });
  },
  read: async ({ work }, use) => {
    await use((path) => {
      const full = inside(work, path);
      return existsSync(full) ? readFileSync(full, "utf8") : null;
    });
  }
});

export { expect };
`;

/** pytest helper. A check does `from thisisfine_check import api, run, write, read`. */
export const PY_HELPER = String.raw`"""Generated by thisisfine; "thisisfine init" rewrites it.

Checks reach the app from outside, never by importing it:

    from thisisfine_check import api, run, write, read

    def test_rejects_an_expired_token():
        r = api.get("/me", headers={"Authorization": "Bearer expired"})
        assert r.status_code == 401
"""
import json
import os
import re
import subprocess
import tempfile
from dataclasses import dataclass
from pathlib import Path

import requests

BASE_URL = os.environ.get("THISISFINE_BASE_URL", "").rstrip("/")
_ROOT = Path(os.environ.get("THISISFINE_WORK") or tempfile.mkdtemp(prefix="thisisfine-"))


def work():
    """This test's scratch directory, where the cli runs (fresh for every test)."""
    test = os.environ.get("PYTEST_CURRENT_TEST", "outside-a-test").split(" ")[0].split("::")[-1]
    full = _ROOT / re.sub(r"[^\w.-]+", "_", test) / "work"
    full.mkdir(parents=True, exist_ok=True)
    return full


class _Api(requests.Session):
    """A requests.Session whose relative URLs go to the app."""

    def __init__(self):
        super().__init__()
        self.trust_env = False  # a system proxy must not sit between a check and localhost

    def request(self, method, url, *args, **kwargs):
        if url.startswith("/"):
            if not BASE_URL:
                raise RuntimeError('thisisfine: no app to call. Set "start" in .thisisfine/config.json.')
            url = BASE_URL + url
        kwargs.setdefault("timeout", 30)
        return super().request(method, url, *args, **kwargs)


api = _Api()


@dataclass
class Result:
    code: int
    out: str
    err: str


def run(*args, input=None, timeout=60):
    """Runs the configured cli with these args. Never raises on a non-zero exit."""
    cli = json.loads(os.environ.get("THISISFINE_CLI") or "null")
    if not cli:
        raise RuntimeError('thisisfine: no cli to run. Set "cli" in .thisisfine/config.json.')
    p = subprocess.run(
        [*cli, *(str(a) for a in args)],
        input=input, capture_output=True, text=True, encoding="utf-8", errors="replace",
        timeout=timeout, env={**os.environ, "THISISFINE_WORK": str(work())},
    )
    return Result(p.returncode, p.stdout, p.stderr)


def _inside(path):
    base = work().resolve()
    full = (base / path).resolve()
    if base not in (full, *full.parents):
        raise ValueError(f"thisisfine: {path} is outside the scratch directory")
    return full


def write(path, text):
    """Writes a file inside the scratch directory, for the cli to read."""
    full = _inside(path)
    full.parent.mkdir(parents=True, exist_ok=True)
    full.write_text(text, encoding="utf-8")
    return full


def read(path):
    """Reads a file the cli wrote in the scratch directory, or None."""
    full = _inside(path)
    return full.read_text(encoding="utf-8") if full.exists() else None
`;

