/** Go helper. A check does `import "thisisfine.local/checks/tif"`. */
export const GO_TIF = String.raw`// Generated by thisisfine; "thisisfine init" rewrites it.
//
// Package tif lets a check reach the app from outside, never by importing it:
//
//	func TestDryRunWritesNothing(t *testing.T) {
//		tif.Write(t, "in.txt", "hello")
//		r := tif.Run(t, "--dry-run", "in.txt")
//		if r.Code != 0 || tif.Exists(t, "out.txt") { t.Fatalf("...") }
//	}
package tif

import (
	"encoding/json"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
	"time"
)

// Result is what the cli did.
type Result struct {
	Code int
	Out  string
	Err  string
}

var unsafe = regexp.MustCompile("[^A-Za-z0-9_.-]+")

// Work is this test's scratch directory, where the cli runs (fresh for every test).
func Work(t testing.TB) string {
	t.Helper()
	root := os.Getenv("THISISFINE_WORK")
	if root == "" {
		root = os.TempDir()
	}
	dir := filepath.Join(root, unsafe.ReplaceAllString(t.Name(), "_"), "work")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

// Run runs the configured cli with these args. A non-zero exit is a Result, not a failure.
func Run(t testing.TB, args ...string) Result {
	t.Helper()
	return RunInput(t, "", args...)
}

// RunInput is Run with stdin.
func RunInput(t testing.TB, input string, args ...string) Result {
	t.Helper()
	var cli []string
	if err := json.Unmarshal([]byte(os.Getenv("THISISFINE_CLI")), &cli); err != nil || len(cli) == 0 {
		t.Fatal("thisisfine: no cli to run. Set \"cli\" in .thisisfine/config.json.")
	}
	cmd := exec.Command(cli[0], append(cli[1:], args...)...)
	cmd.Env = append(os.Environ(), "THISISFINE_WORK="+Work(t))
	cmd.Stdin = strings.NewReader(input)
	var out, errb strings.Builder
	cmd.Stdout, cmd.Stderr = &out, &errb
	err := cmd.Run()
	code := 0
	if err != nil {
		ee, ok := err.(*exec.ExitError)
		if !ok {
			t.Fatalf("thisisfine: couldn't run the cli: %v", err)
		}
		code = ee.ExitCode()
	}
	return Result{Code: code, Out: out.String(), Err: errb.String()}
}

func inside(t testing.TB, path string) string {
	t.Helper()
	work := Work(t)
	full := filepath.Join(work, path)
	if rel, err := filepath.Rel(work, full); err != nil || strings.HasPrefix(rel, "..") {
		t.Fatalf("thisisfine: %s is outside the scratch directory", path)
	}
	return full
}

// Write writes a file inside the scratch directory, for the cli to read.
func Write(t testing.TB, path, text string) string {
	t.Helper()
	full := inside(t, path)
	if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(full, []byte(text), 0o644); err != nil {
		t.Fatal(err)
	}
	return full
}

// Read reads a file the cli wrote in the scratch directory; "" when it isn't there.
func Read(t testing.TB, path string) string {
	t.Helper()
	b, err := os.ReadFile(inside(t, path))
	if err != nil {
		return ""
	}
	return string(b)
}

// Exists says whether the cli left a file in the scratch directory.
func Exists(t testing.TB, path string) bool {
	t.Helper()
	_, err := os.Stat(inside(t, path))
	return err == nil
}

// Response is what the app answered, body read in full.
type Response struct {
	Status int
	Header http.Header
	Body   string
}

// JSON decodes the body into v, failing the check if it isn't JSON.
func (r Response) JSON(t testing.TB, v any) {
	t.Helper()
	if err := json.Unmarshal([]byte(r.Body), v); err != nil {
		t.Fatalf("not JSON (%v): %s", err, r.Body)
	}
}

// Client calls the app through THISISFINE_BASE_URL.
type Client struct {
	t    testing.TB
	base string
	http *http.Client
}

// API returns a client for the app under test.
func API(t testing.TB) *Client {
	t.Helper()
	base := strings.TrimRight(os.Getenv("THISISFINE_BASE_URL"), "/")
	if base == "" {
		t.Fatal("thisisfine: no app to call. Set \"start\" in .thisisfine/config.json.")
	}
	// Proxy: nil, so a system proxy never sits between a check and localhost.
	return &Client{t: t, base: base, http: &http.Client{Timeout: 30 * time.Second, Transport: &http.Transport{Proxy: nil}}}
}

// Do sends a request. header is name, value pairs. A body that starts with { or [ is sent as JSON.
func (c *Client) Do(method, path, body string, header ...string) Response {
	c.t.Helper()
	var rd io.Reader
	if body != "" {
		rd = strings.NewReader(body)
	}
	req, err := http.NewRequest(method, c.base+path, rd)
	if err != nil {
		c.t.Fatal(err)
	}
	if b := strings.TrimSpace(body); strings.HasPrefix(b, "{") || strings.HasPrefix(b, "[") {
		req.Header.Set("Content-Type", "application/json")
	}
	for i := 0; i+1 < len(header); i += 2 {
		req.Header.Set(header[i], header[i+1])
	}
	res, err := c.http.Do(req)
	if err != nil {
		c.t.Fatalf("%s %s: %v", method, path, err)
	}
	defer res.Body.Close()
	b, _ := io.ReadAll(res.Body)
	return Response{Status: res.StatusCode, Header: res.Header, Body: string(b)}
}

// Get is Do("GET", ...).
func (c *Client) Get(path string, header ...string) Response {
	c.t.Helper()
	return c.Do("GET", path, "", header...)
}

// Post is Do("POST", ...).
func (c *Client) Post(path, body string, header ...string) Response {
	c.t.Helper()
	return c.Do("POST", path, body, header...)
}
`;
